with prev_events as (select *, lag(started_at) over (partition by device order by started_at, id) as prev_started_at from sessions), gaps as (select *, case when prev_started_at is null or started_at > prev_started_at + interval 60 days then 1 else 0 end as is_new_burst from prev_events), islands as (select *, sum(is_new_burst) over (partition by device order by started_at, id rows between unbounded preceding and current row) as session_no from gaps) select case when session_no >= 9 then 'LARGE' else 'SMALL' end as session_no_tier, customer_id, session_no, percentile_approx(is_new_burst, array(0.25, 0.5, 0.75)) as is_new_burst_quartiles, min(started_at) as started_at, (unix_timestamp(max(started_at)) - unix_timestamp(min(started_at))) / 60 as duration_min, sum(case when browser = 'Chrome' then session_no else 0 end) as chrome_session_no, count(case when browser = 'Edge' then 1 end) as edge_count from islands group by session_no_tier, customer_id, session_no;
